import React, { useState, useEffect } from "react";
import axios from "axios";

function RecipeGenerator() {
  const [darkMode, setDarkMode] = useState(false);
  const [recipeName, setRecipeName] = useState("");
  const [recipes, setRecipes] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add("dark");
    } else {
      document.documentElement.classList.remove("dark");
    }
  }, [darkMode]);

  const handleSubmit = async () => {
    if (!recipeName.trim()) {
      setError("Please enter a recipe name.");
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const response = await axios.post(
        "https://api.google.com/gemini/v1/generate", // Placeholder endpoint; use actual Gemini API endpoint from Google Cloud
        {
          prompt: `Generate a detailed recipe for ${recipeName} in JSON format. Include the following fields: title (string), ingredients (array of strings), equipment (array of strings), instructions (array of strings), and tips (array of strings). Ensure all fields are present, even if empty.`,
          model: "gemini-1.5-pro", // Adjust based on available models
          response_format: "json",
        },
        {
          headers: {
            "Content-Type": "application/json",
            Authorization: "Bearer YOUR_GEMINI_API_KEY", // Replace with your Google Gemini API key
          },
        }
      );
      const data = response.data;
      if (data && typeof data === "object" && data.title) {
        setRecipes([data]);
      } else {
        // Fallback parsing if JSON format fails
        const textResponse = response.data.text || response.data;
        const fallbackRecipe = {
          title: `Recipe for ${recipeName}`,
          ingredients: ["No ingredients available"],
          equipment: ["No equipment listed"],
          instructions: ["No instructions available"],
          tips: ["No tips available"],
        };
        setRecipes([fallbackRecipe]);
      }
    } catch (err) {
      console.error("API Error:", err);
      setError(
        "Failed to fetch recipe. Check console for details or your API key."
      );
      setRecipes([
        {
          title: `Recipe for ${recipeName}`,
          ingredients: ["No ingredients available"],
          equipment: ["No equipment listed"],
          instructions: ["No instructions available"],
          tips: ["No tips available"],
        },
      ]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className={`min-h-screen bg-gradient-to-b ${
        darkMode ? "from-gray-900 to-gray-800" : "from-white to-gray-100"
      } flex items-center justify-center p-4 transition-colors duration-300 overflow-hidden text-gray-800 dark:text-white`}
    >
      <div className="absolute top-4 right-4 flex space-x-2">
        <button
          onClick={() => setDarkMode(!darkMode)}
          className="bg-gray-800 dark:bg-white text-white dark:text-black px-4 py-2 rounded shadow hover:opacity-80"
        >
          {darkMode ? "☀️" : "🌙"}
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-6xl h-[calc(100vh-2rem)]">
        {/* MIDDLE - Recipe Generator Panel */}
        <div className="bg-white dark:bg-gray-700 dark:text-white rounded-xl shadow-md p-6 flex flex-col h-full">
          <h2 className="text-xl font-bold text-center mb-6">
            Recipe Generator
          </h2>

          <div className="flex-grow space-y-6">
            <div className="space-y-4">
              <div>
                <label
                  className="block font-semibold mb-1"
                  htmlFor="recipeName"
                >
                  Recipe Name
                </label>
                <input
                  id="recipeName"
                  type="text"
                  className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
                  placeholder="e.g. pizza, pasta"
                  value={recipeName}
                  onChange={(e) => setRecipeName(e.target.value)}
                />
              </div>
            </div>
          </div>

          <button
            onClick={handleSubmit}
            className="bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded w-full mt-6"
            disabled={loading}
          >
            {loading ? "Generating..." : "Generate Recipe"}
          </button>
          {error && <p className="text-red-500 text-center mt-2">{error}</p>}
        </div>

        {/* RIGHT - Recipe Output Panel */}
        <div className="bg-white dark:bg-gray-700 rounded-xl shadow-md p-6 flex flex-col h-[calc(100vh-2rem)]">
          <h2 className="text-xl font-bold mb-4 text-center text-gray-800 dark:text-white">
            Recipe Details
          </h2>

          <div className="flex-grow overflow-y-auto">
            {loading && (
              <div className="flex items-center justify-center h-full">
                <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-blue-500"></div>
              </div>
            )}
            {recipes.length > 0 && !loading && (
              <div className="space-y-6">
                {recipes.map((recipe, index) => (
                  <div
                    key={index}
                    className="rounded-xl bg-white dark:bg-gray-800 shadow-md p-4 border dark:border-gray-700"
                  >
                    {recipe.title && (
                      <h3 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-4">
                        {recipe.title}
                      </h3>
                    )}
                    <div>
                      <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2">
                        Ingredients
                      </h4>
                      <ol className="list-decimal list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                        {recipe.ingredients.map((ing, i) => (
                          <li key={i}>{ing}</li>
                        ))}
                      </ol>
                    </div>
                    <div>
                      <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">
                        Equipment
                      </h4>
                      <ul className="list-disc list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                        {recipe.equipment.map((eq, i) => (
                          <li key={i}>{eq}</li>
                        ))}
                      </ul>
                    </div>
                    <div>
                      <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">
                        Instructions
                      </h4>
                      <ol className="list-decimal list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                        {recipe.instructions.map((step, i) => (
                          <li key={i}>{step}</li>
                        ))}
                      </ol>
                    </div>
                    <div>
                      <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">
                        Optional Tips & Variations
                      </h4>
                      <ol className="list-decimal list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                        {recipe.tips.map((tip, i) => (
                          <li key={i}>{tip}</li>
                        ))}
                      </ol>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
      <style>
        {`
          .panel {
            box-sizing: border-box;
            min-height: 0;
            height: auto;
            display: flex;
            flex-direction: column;
          }
        `}
      </style>
    </div>
  );
}

export default RecipeGenerator;
